-- fsfs_tags.sql — 의상 태그·보온·색상(컬러웨이)·수선집·안경점·태닝샵 (2026-11-14). 여러 번 실행해도 안전해요.
-- 1) 칸·테이블
alter table fsfs_item add column if not exists warmth smallint;
alter table fsfs_asset add column if not exists area integer;
alter table fsfs_asset add column if not exists role text;
alter table fsfs_npc add column if not exists likes text[] not null default '{}';
comment on column fsfs_npc.likes is '좋아하는 옷 색(색 이름). 그 색 옷을 입고 호감도가 오르는 행동을 하면 하루 한 번 +1';
comment on column fsfs_item.warmth is '보온 점수 0~5 (입은 옷의 합으로 날씨에 맞는지 봐요)';
comment on column fsfs_asset.area is '칠해진 픽셀 수 (가장 넓은 fill = 대표색)';
comment on column fsfs_asset.role is '바디 레이어의 구실: skin 피부(태닝) · white 흰자위 · iris 눈동자(렌즈가 보이는 영역) · etc 그 밖 · 비우면 색으로 짐작';
create table if not exists fsfs_tag(name text primary key, cat text not null check (cat in ('style','pattern','use')), sort integer not null default 0);
create table if not exists fsfs_colorway(id uuid primary key default gen_random_uuid(), item_id uuid not null references fsfs_item(id) on delete cascade,
  name text not null, colors jsonb not null default '{}'::jsonb, sort integer not null default 0, enabled boolean not null default true, created_at timestamptz not null default now());
create index if not exists fsfs_colorway_item on fsfs_colorway(item_id);
alter table fsfs_tag enable row level security; alter table fsfs_colorway enable row level security;
do $$ begin
  if not exists (select 1 from pg_policies where tablename='fsfs_tag' and policyname='fsfs_tag_sel') then create policy fsfs_tag_sel on fsfs_tag for select to anon, authenticated using (true); end if;
  if not exists (select 1 from pg_policies where tablename='fsfs_tag' and policyname='fsfs_tag_w') then create policy fsfs_tag_w on fsfs_tag for all to authenticated using (fsfs_is_admin()) with check (fsfs_is_admin()); end if;
  if not exists (select 1 from pg_policies where tablename='fsfs_colorway' and policyname='fsfs_colorway_sel') then create policy fsfs_colorway_sel on fsfs_colorway for select to anon, authenticated using (true); end if;
  if not exists (select 1 from pg_policies where tablename='fsfs_colorway' and policyname='fsfs_colorway_w') then create policy fsfs_colorway_w on fsfs_colorway for all to authenticated using (fsfs_is_admin()) with check (fsfs_is_admin()); end if;
end $$;
