insert into fsfs_colorway(item_id,name,colors,sort) select '1c8f9064-ed65-4ed3-ac7c-e9cef2bc9e78',v.n,v.c::jsonb,v.s from (values ('민트','{"fill1":"#4a4543","fill2":"#5abb9b"}',0),('파랑','{"fill1":"#4a4543","fill2":"#5a72bb"}',1),('분홍','{"fill1":"#4a4543","fill2":"#bb5a93"}',2),('흰색','{"fill1":"#4a4543","fill2":"#f1ebe6"}',3)) v(n,c,s) where exists(select 1 from fsfs_item where id='1c8f9064-ed65-4ed3-ac7c-e9cef2bc9e78') and not exists(select 1 from fsfs_colorway where item_id='1c8f9064-ed65-4ed3-ac7c-e9cef2bc9e78');
